5	/// Extension trait for converting various result types into
6	/// `wasmtime::Result`s.
7	///
8	/// This is a small convenience helper to replace
9	/// `anyhow_result.map_err(wasmtime::Error::from_anyhow)` with
10	/// `anyhow_result.to_wasmtime_result()`.
11	///
12	/// An identity implementation is also provided for `wasmtime::Result<T>` so
13	/// that this trait can be used regardless of whether the `"anyhow"` cargo
14	/// feature is enabled. The `anyhow::Result<T>` implementation requires the
15	/// `"anyhow"` cargo feature.
16	///
17	/// # Example
18	///
19	/// ```
20	/// # fn _foo() {
21	/// #![cfg(feature = "anyhow")]
22	/// # use wasmtime_internal_core::error as wasmtime;
23	/// use wasmtime::ToWasmtimeResult as _;
24	///
25	/// fn returns_anyhow_result() -> anyhow::Result<u32> {
26	///     anyhow::bail!("eep")
27	/// }
28	///
29	/// fn returns_wasmtime_result() -> wasmtime::Result<()> {
30	///     // The following is equivalent to
31	///     //
32	///     //     returns_anyhow_result()
33	///     //         .map_err(wasmtime::Error::from_anyhow)?;
34	///     returns_anyhow_result().to_wasmtime_result()?;
35	///     Ok(())
36	/// }
37	///
38	/// let error: wasmtime::Error = returns_wasmtime_result().unwrap_err();
39	/// assert!(error.is::<anyhow::Error>());
40	/// assert_eq!(error.to_string(), "eep");
41	/// # }
42	/// ```
43	pub trait ToWasmtimeResult<T> {
44	    /// Convert this result into a `wasmtime::Result<T>`.
45	    fn to_wasmtime_result(self) -> Result<T>;
46	}
47	
48	#[cfg(feature = "anyhow")]
49	impl<T> ToWasmtimeResult<T> for anyhow::Result<T> {
50	    #[inline]
51	    fn to_wasmtime_result(self) -> Result<T> {
52	        match self {
53	            Ok(x) => Ok(x),
54	            Err(e) => Err(Error::from_anyhow(e)),
55	        }
56	    }
57	}
58	
59	impl<T> ToWasmtimeResult<T> for Result<T> {
60	    #[inline]
61	    fn to_wasmtime_result(self) -> Result<T> {
62	        self
63	    }
